<style>
.xd4-page .tc-contact-page{--tc-accent:var(--xd4-green);padding:0 0 72px;background:#f4f6f2;color:var(--xd4-ink);font-family:var(--theme-font-body)}
.xd4-page .tc-contact-container{width:min(1240px,calc(100% - 64px))}
.xd4-page .tc-contact-breadcrumb{padding:26px 0;color:var(--xd4-muted);font-size:12px}
.xd4-page .tc-contact-heading{max-width:760px;padding:12px 0 36px}
.xd4-page .tc-contact-heading>span{display:inline-flex;align-items:center;gap:10px;color:#557a1b;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
.xd4-page .tc-contact-heading>span:before{content:"";width:24px;height:3px;background:var(--xd4-green)}
.xd4-page .tc-contact-heading h1{font-family:var(--theme-font-display);font-size:clamp(32px,3.5vw,46px);font-weight:700;line-height:1.2;letter-spacing:normal;margin:12px 0 14px;color:var(--xd4-ink)}
.xd4-page .tc-contact-heading p{max-width:660px;color:var(--xd4-muted);font-size:15px;line-height:1.8}
.xd4-page .tc-contact-layout{grid-template-columns:minmax(0,.85fr) minmax(0,1.25fr);gap:32px;align-items:stretch}
.xd4-page .tc-contact-info{position:relative;padding:36px;border:0;border-radius:10px;background:var(--xd4-ink);color:#fff;overflow:hidden}
.xd4-page .tc-contact-info:after{content:"";position:absolute;right:-70px;bottom:-100px;width:240px;height:240px;border:1px solid #ffffff0c;border-radius:50%;pointer-events:none}
.xd4-page .tc-contact-layout h2{font-family:var(--theme-font-display);font-size:24px;font-weight:700;margin:0 0 10px}
.xd4-page .tc-contact-info h2{color:#fff}
.xd4-page .tc-contact-info>p{max-width:320px;color:#c8cfcb;font-size:14px;line-height:1.8;margin-bottom:30px}
.xd4-page .tc-contact-item{padding:24px 0;border-color:#ffffff24;gap:18px}
.xd4-page .tc-contact-item>.tc-contact-icon{background:#ffffff0c;border:1px solid #ffffff14;border-radius:8px;color:var(--xd4-green);flex-basis:44px;height:44px}
.xd4-page .tc-contact-item h3{font-family:var(--theme-font-body);font-size:12px;font-weight:500;color:#aab5ae;margin-bottom:5px}
.xd4-page .tc-contact-item p,.xd4-page .tc-contact-item a{color:#fff;font-size:15px;line-height:1.8}
.xd4-page .tc-contact-item .tc-contact-directions{color:#b4d97c;font-size:12px}
.xd4-page .tc-contact-form-card{padding:36px;border:1px solid #e1e7db;border-top:4px solid var(--xd4-green);border-radius:10px;box-shadow:0 16px 40px #22272908}
.xd4-page .tc-contact-form-card>p{color:var(--xd4-muted);margin-bottom:26px}
.xd4-page .tc-contact-fields{gap:20px}
.xd4-page .tc-contact-fields label{color:var(--xd4-ink);font-size:13px}
.xd4-page .tc-contact-fields input,.xd4-page .tc-contact-fields textarea{font-family:var(--theme-font-body);font-size:14px;color:var(--xd4-ink);border-color:#d7dfd1;border-radius:6px;background:#fbfcfa;padding:12px 14px}
.xd4-page .tc-contact-fields input{min-height:46px}
.xd4-page .tc-contact-fields textarea{min-height:130px}
.xd4-page .tc-contact-fields small{color:var(--xd4-muted);font-size:12px}
.xd4-page .tc-contact-fields [aria-invalid=true]{border-color:#c43939}
.xd4-page .tc-contact-form-card button{width:100%;min-height:48px;border-radius:6px;background:var(--xd4-green);color:var(--xd4-ink);font-family:var(--theme-font-body);font-weight:700;margin-top:24px;padding:12px 24px}
.xd4-page .tc-contact-form-card button:hover{background:#a0cc4f}
.xd4-page .tc-contact-form-card button:disabled{opacity:.7;cursor:wait}
.xd4-page .tc-contact-copy{font-size:15px;color:var(--xd4-muted)}
@media(max-width:800px){.xd4-page .tc-contact-layout{grid-template-columns:minmax(0,1fr);gap:24px}.xd4-page .tc-contact-info>p{max-width:none}.xd4-page .tc-contact-info,.xd4-page .tc-contact-form-card{padding:28px}.xd4-page .tc-contact-heading{padding-bottom:28px}}
@media(max-width:480px){.xd4-page .tc-contact-container{width:calc(100% - 32px)}.xd4-page .tc-contact-page{padding-bottom:40px}.xd4-page .tc-contact-info,.xd4-page .tc-contact-form-card{padding:24px 20px}.xd4-page .tc-contact-heading h1{font-size:32px}.xd4-page .tc-contact-fields{grid-template-columns:minmax(0,1fr);gap:16px}}
</style>
